-- LPNOAI: live-prep's paper layer's formula reward per market and day (pm_lpprep_minutes, 10-05 -> 10-09 UTC; its dry-run
-- ran until 10-09 01:32) and every selection since 10-05 with its question, read-only. Padded so the connector saves the
-- reply to a file; data/lp_record.json is its payload.
select jsonb_build_object('pad', repeat('x', 300000), 'paper', (select jsonb_agg(jsonb_build_object('day', d, 'cond', cond, 'reward', rew, 'minutes', n, 'question', question) order by d, cond) from (select (m.minute at time zone 'UTC')::date d, m.cond, round(sum(coalesce(m.reward,0))::numeric, 6) rew, count(*) n from public.pm_lpprep_minutes m where m.minute >= '2026-10-05' and m.minute < '2026-10-10' group by 1,2) r left join (select distinct on (cond) cond, question from public.pm_lp_markets order by cond, day desc) q using (cond)), 'selections', (select jsonb_agg(jsonb_build_object('day', day, 'cond', cond, 'rank', rank, 'rate', reward_rate, 'question', question) order by day, rank) from public.pm_lp_markets where day >= '2026-10-05')) payload
